<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue';
import api from '@/services/mercado.services';
import AppBrand from '@/components/AppBrand.vue';
import { BRAND } from '@/config/brand';
const products=ref([]), categories=ref([]), total=ref(0), page=ref(1), loading=ref(true), error=ref(false);
const search=ref(''), category=ref(''), available=ref(false), sort=ref('recent'), selected=ref(null), failedImages=ref({});
const hasFilters=computed(()=>!!(search.value.trim() || category.value || available.value || sort.value!=='recent'));
const money=value=>new Intl.NumberFormat('es-SV',{style:'currency',currency:'USD'}).format(Number(value));
let request=0, timer;
async function load(){ const current=++request; loading.value=true; error.value=false; try { const {data}=await api.catalog(page.value,{q:search.value.trim() || undefined,category:category.value || undefined,available:available.value || undefined,sort:sort.value}); if(current===request){products.value=data.items;total.value=data.total;} } catch { if(current===request){error.value=true;products.value=[];total.value=0;} } finally {if(current===request)loading.value=false;} }
function applyFilters(){clearTimeout(timer);page.value=1;load();}
function chooseCategory(value){category.value=value;applyFilters();}
function clearFilters(){search.value='';category.value='';available.value=false;sort.value='recent';applyFilters();}
watch(search,()=>{clearTimeout(timer); ++request; loading.value=true; timer=setTimeout(applyFilters,350);});
onMounted(async()=>{load();try{categories.value=(await api.categories()).data;}catch{categories.value=[];}});
onBeforeUnmount(()=>{clearTimeout(timer);++request;});
</script>
